    const quantityChangeHandler = function() {
        const parent = $(this).parent();
        let quantity = $(this).val();

        if (quantity == '' || quantity <= 0) {
            quantity = 1;
            $(this).val(quantity);
            parent.find('.minus').attr('disabled', true);
        } else if (quantity == 1) {
            parent.find('.minus').attr('disabled', true);
        } else {
            parent.find('.minus').removeAttr('disabled');
